//! Extended, opt-in local model catalog (`shared/models/catalog.json`).
//!
//! Generated by `shared/scripts/build_model_catalog.py` from trusted
//! Hugging Face publishers. Every file is pinned to an immutable revision and
//! SHA256, so catalog models go through the same verified downloader and
//! provenance checks as the curated registry. The curated defaults in
//! `registry.rs` / `manifest.json` always win over a catalog entry.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::OnceLock;

const CATALOG_JSON: &str = include_str!("../../../../../../shared/models/catalog.json");

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct CatalogFile {
    pub role: String,
    pub path: String,
    pub sha256: Option<String>,
    pub bytes: Option<u64>,
    pub url: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct CatalogEntry {
    pub id: String,
    pub name: String,
    pub family: String,
    pub upstream: String,
    pub repo: String,
    pub revision: String,
    pub format: String,
    pub role: String,
    pub quantization: String,
    pub license: String,
    pub terms_required: bool,
    pub parameters_billion: Option<f64>,
    pub active_parameters_billion: Option<f64>,
    pub download_bytes: u64,
    #[serde(rename = "estimatedResidentGB")]
    pub estimated_resident_gb: f64,
    pub tier: String,
    pub platforms: Vec<String>,
    pub files: Vec<CatalogFile>,
    pub status: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CatalogDocument {
    schema_version: u32,
    entries: Vec<CatalogEntry>,
}

struct Catalog {
    entries: Vec<CatalogEntry>,
    directories: HashMap<String, &'static str>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let document: CatalogDocument = serde_json::from_str(CATALOG_JSON).unwrap_or(CatalogDocument { schema_version: 1, entries: vec![] });
        let entries: Vec<CatalogEntry> = if document.schema_version == 1 { document.entries.into_iter().filter(valid).collect() } else { vec![] };
        // Directory names are leaked once so the registry can keep handing
        // out `&'static str` keys for catalog models like curated ones.
        let directories = entries
            .iter()
            .map(|entry| (entry.id.clone(), &*Box::leak(format!("catalog-{}", entry.id).into_boxed_str())))
            .collect();
        Catalog { entries, directories }
    })
}

/// Rejects entries the engine must never download: unpinned or non-HF
/// files, unsafe ids, or a license outside the allowed set.
fn valid(entry: &CatalogEntry) -> bool {
    let id_ok = !entry.id.is_empty() && entry.id.len() <= 120 && entry.id.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_');
    let license_ok = matches!(entry.license.as_str(), "Apache-2.0" | "MIT") || (entry.license == "Gemma" && entry.terms_required);
    let files_ok = !entry.files.is_empty()
        && entry.files.iter().all(|file| {
            file.sha256.as_deref().is_some_and(|sha| sha.len() == 64 && sha.bytes().all(|b| b.is_ascii_hexdigit()))
                && file.url.starts_with(&format!("https://huggingface.co/{}/resolve/{}/", entry.repo, entry.revision))
                && !file.path.contains("..")
        });
    let revision_ok = entry.revision.len() == 40 && entry.revision.bytes().all(|b| b.is_ascii_hexdigit());
    id_ok && license_ok && files_ok && revision_ok
}

pub fn entries() -> &'static [CatalogEntry] {
    &catalog().entries
}

pub fn find(id: &str) -> Option<&'static CatalogEntry> {
    catalog().entries.iter().find(|entry| entry.id == id)
}

/// A catalog model the shared engine can run today: a llama.cpp vision
/// model (weights plus projector) offered on this platform.
pub fn runnable_vision(id: &str) -> Option<&'static CatalogEntry> {
    let platform = if cfg!(windows) { "windows" } else if cfg!(target_os = "macos") { "macos" } else { "linux" };
    find(id).filter(|entry| {
        entry.format == "gguf"
            && entry.role == "vision"
            && entry.platforms.iter().any(|p| p == platform)
            && entry.files.iter().any(|f| f.role == "model")
            && entry.files.iter().any(|f| f.role == "projector")
    })
}

/// Directory under `Models/vlm/` for a runnable catalog vision model.
pub(crate) fn directory(id: &str) -> Option<&'static str> {
    runnable_vision(id).and_then(|entry| catalog().directories.get(&entry.id).copied())
}

